import{_ as e,a as t,b as a,c as r,d as n,e as s,f as i,g as l,h as u}from"./chunks/sound-wave.UVZ-guYw.js";import{_ as d,o as h,c as p,a2 as c}from"./chunks/framework.Bzj1XTnB.js";const v=JSON.parse('{"title":"Sound","description":"Add sound effects, music jingles and voices from the free library, make a voice, record yourself and line sound up with your frames.","frontmatter":{"lang":"en","slug":"sound","order":8,"title":"Sound","description":"Add sound effects, music jingles and voices from the free library, make a voice, record yourself and line sound up with your frames."},"headers":[],"relativePath":"sound.md","filePath":"sound.md"}'),g={name:"sound.md"};function m(y,o,f,b,_,k){return h(),p("div",null,[...o[0]||(o[0]=[c('<h1 id="sound" tabindex="-1">Sound <a class="header-anchor" href="#sound" aria-label="Permalink to &quot;Sound&quot;">​</a></h1><p>Tap <strong>Audio</strong> in the bottom bar to open the audio editor.</p><p><img src="'+e+'" alt="Audio editor"></p><ul><li>The <strong>preview</strong> at the top shows the frame under the blue playhead.</li><li><strong>🔊</strong> mutes or unmutes all sound while you work.</li><li><strong>⏮ ▶ ⏭</strong> — play from here, or jump to the start or end.</li><li>The four buttons on the right: <strong>Sound FX</strong> (opens the sound library), <strong>Voice maker</strong>, <strong>Record audio</strong> and <strong>Import audio</strong> (music, or the sound of a video file, from your phone).</li><li>There are <strong>6 tracks</strong>, so sounds can play at the same time. Each track can be muted or locked.</li><li>Your frames run along the bottom, so you can line a sound up with the exact drawing.</li></ul><p>New sounds are placed at the playhead. <strong>Drag</strong> a clip to move it, drag its ends to trim it, and <strong>pinch</strong> to zoom in for precise timing.</p><h2 id="clip-actions" tabindex="-1">Clip actions <a class="header-anchor" href="#clip-actions" aria-label="Permalink to &quot;Clip actions&quot;">​</a></h2><p><strong>Long-press a clip</strong> for <strong>Rename</strong>, <strong>Duplicate</strong>, <strong>Split at playhead</strong>, <strong>Volume</strong> and <strong>Delete</strong>.</p><p><img src="'+t+'" alt="Clip actions"></p><h2 id="the-sound-library" tabindex="-1">The sound library <a class="header-anchor" href="#the-sound-library" aria-label="Permalink to &quot;The sound library&quot;">​</a></h2><p><strong>169 sounds, all free to use</strong> in your animations, in themed packs: Toonik basics, Fight, Cartoon &amp; game, Footsteps &amp; moves, Home &amp; objects, Sci-fi &amp; machines, Clicks &amp; alerts, Music jingles and Voices (an announcer saying &quot;3, 2, 1, Go!&quot;, &quot;You win&quot;, &quot;Game over&quot;…).</p><p><img src="'+a+'" alt="Sound library"></p><p>Open a pack, tap <strong>▶</strong> to listen and <strong>+ ADD</strong> to put it on the timeline. Every sound has a short description of what it sounds like.</p><p><img src="'+r+'" alt="A sound pack"></p><h3 id="searching" tabindex="-1">Searching <a class="header-anchor" href="#searching" aria-label="Permalink to &quot;Searching&quot;">​</a></h3><p>Type what you want to hear, in your own words — one word or a whole sentence:</p><ul><li>&quot;door&quot; · &quot;someone slamming the door shut&quot; · &quot;footsteps on snow&quot; · &quot;laser gun&quot; · &quot;a happy win tune&quot;</li></ul><p>Hindi words in English letters work too:</p><ul><li>&quot;bada dhamaka&quot; · &quot;darwaza band&quot; · &quot;jeet&quot; · &quot;paisa&quot;</li></ul><p>The best matches come first.</p><p><img src="'+n+'" alt="Searching with a sentence"></p><p><img src="'+s+'" alt="Searching in Hinglish"></p><p>The sound packs are by Kenney (kenney.nl) and are public domain, so you can use them in anything you make, even videos you earn money from.</p><h2 id="voice-maker" tabindex="-1">Voice maker <a class="header-anchor" href="#voice-maker" aria-label="Permalink to &quot;Voice maker&quot;">​</a></h2><p>Type a line, pick a <strong>Voice</strong> (Normal, Kid, Deep, Squeaky, Sleepy) and a <strong>Language</strong> (English or Hindi), tap <strong>Preview</strong> to hear it and <strong>Add to timeline</strong>.</p><p><img src="'+i+'" alt="Voice maker"></p><h2 id="record-your-voice" tabindex="-1">Record your voice <a class="header-anchor" href="#record-your-voice" aria-label="Permalink to &quot;Record your voice&quot;">​</a></h2><p>Tap <strong>Record audio</strong>, allow the microphone the first time, then <strong>hold the button</strong> to record and release to stop. Switch on <strong>Play animation while recording</strong> to speak in time with your drawings. Recording starts at the current frame.</p><p><img src="'+l+'" alt="Record audio"></p><h2 id="animate-to-the-beat" tabindex="-1">Animate to the beat <a class="header-anchor" href="#animate-to-the-beat" aria-label="Permalink to &quot;Animate to the beat&quot;">​</a></h2><p>Turn on <strong>Sound while animating</strong> in <strong>App settings → Sound</strong> (it is off until you do). Then:</p><ul><li><strong>Each frame&#39;s sound plays</strong> as you step to it or drag the frame strip, so you can hear exactly where a word or a hit lands.</li><li>A <strong>pink note</strong> sits above every frame a beat falls on — a drum hit, a clap, a plucked note. Put your key poses there.</li><li><strong>The sound wave stays on screen while you play</strong> the animation: the wave going by (already played in pink), a dot on every beat, and the playhead in the middle lighting up as a beat passes. The wave button in the top bar, next to the diamond, hides or shows it.</li></ul><p><img src="'+u+'" alt="Sound wave while playing"></p>',32)])])}const S=d(g,[["render",m]]);export{v as __pageData,S as default};
